import{_ as e,o as r,c as n,a2 as a}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Glossary","description":"Shared explanations of Hearth product and engineering concepts.","frontmatter":{"title":"Glossary","description":"Shared explanations of Hearth product and engineering concepts.","outline":false},"headers":[],"relativePath":"en/reference/glossary.md","filePath":"en/reference/glossary.md","lastUpdated":1794305977000}'),d={name:"en/reference/glossary.md"};function o(i,t,s,c,l,p){return r(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p class="lead">A word should mean the same thing in the documentation, the interface, and the implementation. These are the concepts Hearth uses most often, explained in user-facing language first.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Hearth</td><td>A single-user, self-hosted, long-running personal Agent OS</td></tr><tr><td>Task</td><td>A unit of work the user wants completed, verified, and recoverable</td></tr><tr><td>Goal contract</td><td>A record fixed before execution that holds the goal, constraints, acceptance criteria, forbidden actions, budget, deadline, stop conditions, and review policy</td></tr><tr><td>Completion judgement</td><td>The process of checking each acceptance criterion and its evidence to return pass, fail, human review, or blocked</td></tr><tr><td>Evidence report</td><td>A task record of criterion results, evidence references, missing evidence, forbidden actions, and check time</td></tr><tr><td>Work unit</td><td>A small authorized piece of a task that can run and be verified on its own</td></tr><tr><td>Execution record</td><td>The input, result, artifacts, and failure reason from one real attempt</td></tr><tr><td>Fact record</td><td>An append-only system record from which interfaces, reports, and notifications are rebuilt</td></tr><tr><td>Checkpoint</td><td>A recoverable state saved during long-running work</td></tr><tr><td>Snapshot</td><td>A copy of a workspace or data state used for recovery or comparison</td></tr><tr><td>Executor</td><td>A controlled capability that completes a kind of work, such as general reasoning, Codex, a browser, or desktop operation</td></tr><tr><td>Connector</td><td>An official interface to an external system such as email, calendar, or cloud storage</td></tr><tr><td>Delegation</td><td>A parent task assigns a bounded child piece of work to another execution path while inheriting the parent&#39;s constraints and remaining budget</td></tr><tr><td>Handoff packet</td><td>The diagnosis, completed work, evidence, open items, remaining budget, and generation needed to continue</td></tr><tr><td>Sandbox</td><td>A policy boundary over paths, processes, network, and credentials; the current local implementation is not a strong container or VM</td></tr><tr><td>Authorization scope</td><td>The objects, time, and risk level within which an action is allowed</td></tr><tr><td>Approval</td><td>The user&#39;s confirmation of one specific external action</td></tr><tr><td>External effect</td><td>A real-world impact such as sending, writing, deleting, publishing, paying, or operating a device</td></tr><tr><td>Receipt</td><td>A verifiable result left after an external action happens</td></tr><tr><td>Reconciliation</td><td>Querying external state when a result is uncertain to determine whether an action happened</td></tr><tr><td>Personal ontology</td><td>Entities, aliases, relations, states, decisions, and commitments with provenance, confidence, sensitivity, and validity</td></tr><tr><td>Context Pack</td><td>Context assembled for an executor by scope, budget, and channel, separating must-know, relevant, recallable, and explicitly omitted material</td></tr><tr><td>Standing intent</td><td>A long-lived user rule or concern that the heartbeat turns into attention candidates instead of directly executing actions</td></tr><tr><td>Attention budget</td><td>Interruption limits such as daily caps, quiet hours, category cooldown, per-target limits, and a high-priority cap</td></tr><tr><td>Connection runtime</td><td>The device-connection layer that separates transport, subscription, data freshness, and execution ownership and uses generations to fence old sessions</td></tr><tr><td>Offline outbox</td><td>A queue of pending actions kept while a device is offline; reconnect submits by idempotency key and never blindly replays external effects</td></tr><tr><td>Artifact</td><td>A file, report, spreadsheet, link, or other deliverable produced by a task</td></tr><tr><td>Memory</td><td>Long-term or medium-term context with provenance, scope, and sensitivity</td></tr><tr><td>Method</td><td>A verified, reusable procedure or tool recipe</td></tr><tr><td>Evaluation</td><td>Judging capability with real tasks, baselines, verifiers, and cost metrics</td></tr><tr><td>Canary</td><td>Limited real use of a new method before wider adoption</td></tr><tr><td>Stop switch</td><td>An entry point for pausing tasks, devices, or all external actions during an incident</td></tr><tr><td>Verified completion</td><td>Real completion supported by artifacts, evidence, and necessary receipts</td></tr></tbody></table>',3)])])}const f=e(d,[["render",o]]);export{u as __pageData,f as default};
